// Checks 1 & 2 of Section 6 / doc Section 3.4 (suppression + entitlement) only.
const ctx = $node["When Called by Another Workflow"].json;

// Safe retrieval handling both object and array formats
const candidate = $node["Supabase - Get Candidate"]?.json[0] || $node["Supabase - Get Candidate"]?.json;
const account = $node["Supabase - Get Account (tier)"]?.json[0] || $node["Supabase - Get Account (tier)"]?.json;
const roundData = $node["Supabase - Get Round Instance & Campaign"]?.json;
const roundInstance = Array.isArray(roundData) ? roundData[0] : roundData;

// Normalize stage to database notification_templates canonical names
const rawStage = String(ctx.stage || '').toLowerCase().trim();
const STAGE_MAP = {
  'candidate_rejected': 'result_not_selected',
  'rejected': 'result_not_selected',
  'booking_reminder_1': 'booking_reminder_day1',
  'reminder_day1': 'booking_reminder_day1',
  'booking_reminder_2': 'booking_reminder_day3',
  'reminder_day3': 'booking_reminder_day3',
  'reminder_day5': 'booking_final_notice',
  'pre_interview_reminder': 'pre_interview_24h',
  'pre_interview': 'pre_interview_24h',
  'interview_link_dispatch': 'interview_link_today',
  'interview_link': 'interview_link_today',
  'interview_day': 'interview_link_today',
  'assignment_midpoint_reminder': 'assignment_checkin',
  'assignment_deadline_24h': 'assignment_reminder_24h',
  'assignment_invite': 'assignment_issued',
  'round_passed': 'result_next_round'
};
const canonicalStage = STAGE_MAP[rawStage] || rawStage;

// 1. Suppression: Only suppress if candidate missing, opted out, or already rejected (unless this IS a rejection notification)
const isRejectionStage = canonicalStage === 'result_not_selected';
if (!candidate || candidate.opted_out || (!isRejectionStage && candidate.status === 'rejected')) {
  return [{ json: { ...ctx, stage: canonicalStage, decision: 'suppressed', reason: 'candidate_rejected_or_opted_out' } }];
}

// 2. Entitlement (tier -> channel map)
const tier = account?.tier || 'free';
const TIER_CHANNELS = {
  free: ['email'],
  basic: ['email', 'whatsapp', 'voice_call'],
  growth: ['email', 'whatsapp', 'voice_call'],
  enterprise: ['email', 'whatsapp', 'voice_call', 'sms']
};
const allowedChannels = TIER_CHANNELS[tier] || ['email'];

// Normalize phone to E.164 without leading +
let rawPhone = String(candidate.phone || '').replace(/\D/g, '');
let phone = rawPhone;
if (phone.length === 10) {
  phone = '91' + phone;
} else if (phone.startsWith('0')) {
  phone = '91' + phone.slice(1);
}

// Dual-dispatch: Send both Email and WhatsApp when available
const isEmailOnly = ctx.preferred_channel === 'email' || ctx.preferred_channel === 'email_only';
const isWaOnly = ctx.preferred_channel === 'whatsapp_only';

const sendEmail = !!candidate.email && !isWaOnly;
const sendWhatsApp = !!phone && allowedChannels.includes('whatsapp') && !isEmailOnly;

const candName = candidate.name || ctx.candidate_name || 'Candidate';
const firstName = candName.trim().split(' ')[0] || 'there';
const companyName = account?.company_name || 'ScalePods';

// Resolve Role from campaign name (linked via round_instance), context, or candidate
const campaignObj = Array.isArray(roundInstance?.campaigns) ? roundInstance?.campaigns[0] : roundInstance?.campaigns;
const roleFromCampaign = campaignObj?.name || '';
const roleTitle = ctx.role_title || ctx.job_title || roleFromCampaign || candidate?.role_title || 'Candidate Role';

return [{
  json: {
    ...ctx,
    stage: canonicalStage,
    decision: 'proceed',
    send_email: sendEmail,
    send_whatsapp: sendWhatsApp,
    channel: (sendEmail && sendWhatsApp) ? 'both' : (sendWhatsApp ? 'whatsapp' : 'email'),
    tier,
    candidate_name: candName,
    candidate_first_name: firstName,
    candidate_email: candidate.email,
    candidate_phone: phone,
    company_name: companyName,
    role_title: roleTitle,
    job_title: roleTitle
  }
}];

