  (() => {
    const cand = $node["Suppression & Entitlement Check"].json;
    const tmpl = ($node["Supabase - Resolve WhatsApp Template"].json?.[0] || $node["Supabase - Resolve WhatsApp Template"].json || $json[0] || $json || {});
    const templateName = tmpl.meta_template_name || 'interview_invite_v1';
