const ctx = $node['Suppression & Entitlement Check'].json;
const data = $node['Supabase - Get Round Instance & Campaign'].json;
const round = Array.isArray(data) ? data[0] : data;

const stage = String(ctx.stage || '').toLowerCase();

// Determine access token type (including rejection)
let type = null;
if (round?.round_type === 'assignment' || stage.startsWith('assignment')) {
  type = 'assignment';
} else if (round?.round_type === 'human_interview' || stage.includes('interview')) {
  type = 'booking';
} else if (stage.includes('reject')) {
  type = 'rejection';
}

let token = null;
let tokenHash = null;

// Removed `ctx.round_instance_id` requirement so tokens generate even if round_instance_id is empty ("")
if (type) {
  // Pure JS random 32-byte (64 hex characters) token generation
  let chars = '';
  for (let i = 0; i < 64; i++) {
    chars += Math.floor(Math.random() * 16).toString(16);
  }
  token = chars;

  // Pure JS SHA-256 Hash implementation
  function sha256(ascii) {
    const mathPow = Math.pow;
    const maxWord = mathPow(2, 32);
    const lengthProperty = 'length';
    let i, j;
    let result = '';

    const words = [];
    const asciiBitLength = ascii[lengthProperty] * 8;

    let hash = sha256.h = sha256.h || [];
    let k = sha256.k = sha256.k || [];
    let primeCounter = k[lengthProperty];

    const isPrime = function(candidate) {
      for (let factor = 2; factor * factor <= candidate; factor++) {
        if (candidate % factor === 0) return false;
      }
      return true;
    };

    let candidate = 2;
    while (primeCounter < 64) {
      if (isPrime(candidate)) {
        if (primeCounter < 8) {
          hash[primeCounter] = (mathPow(candidate, 1/2) * maxWord) | 0;
        }
        k[primeCounter] = (mathPow(candidate, 1/3) * maxWord) | 0;
        primeCounter++;
      }
      candidate++;
    }

    hash = hash.slice(0);
    ascii += '\x80';
    while (ascii[lengthProperty] % 64 - 56) ascii += '\x00';
    for (i = 0; i < ascii[lengthProperty]; i++) {
      j = ascii.charCodeAt(i);
      if (j >> 8) return;
      words[i >> 2] |= j << ((3 - i % 4) * 8);
    }
    words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
    words[words[lengthProperty]] = (asciiBitLength);

    for (j = 0; j < words[lengthProperty];) {
      const w = words.slice(j, j += 16);
      const oldHash = hash;
      hash = hash.slice(0, 8);

      for (i = 0; i < 64; i++) {
        const w15 = w[i - 15], w2 = w[i - 2];
        const a = hash[0], e = hash[4];
        const temp1 = hash[7]
          + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
          + ((e & hash[5]) ^ ((~e) & hash[6]))
          + k[i]
          + (w[i] = (i < 16) ? w[i] : (
              w[i - 16]
              + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
              + w[i - 7]
              + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
            ) | 0
          );
        const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
          + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));

        hash = [(temp1 + temp2) | 0].concat(hash);
        hash[4] = (hash[4] + temp1) | 0;
      }

      for (i = 0; i < 8; i++) {
        hash[i] = (hash[i] + oldHash[i]) | 0;
      }
    }

    for (i = 0; i < 8; i++) {
      for (j = 3; j >= 0; j--) {
        const b = (hash[i] >> (j * 8)) & 255;
        result += (b < 16 ? 0 : '') + b.toString(16);
      }
    }
    return result;

    function rightRotate(value, amount) {
      return (value >>> amount) | (value << (32 - amount));
    }
  }

  tokenHash = sha256(token);
}

return [{
  json: {
    ...ctx,
    access_token: token,
    access_token_hash: tokenHash,
    access_token_type: type,
    access_token_expiry: new Date(Date.now() + 30 * 86400000).toISOString()
  }
}];

